CREATE TABLE IF NOT EXISTS candidate_evaluations(id INTEGER PRIMARY KEY AUTOINCREMENT,candidate_id INTEGER NOT NULL UNIQUE REFERENCES prediction_candidates(id),entry_snapshot_id INTEGER NOT NULL REFERENCES scanner_snapshots(id),exit_snapshot_id INTEGER NOT NULL REFERENCES scanner_snapshots(id),entry_price REAL NOT NULL CHECK(entry_price>0),exit_price REAL NOT NULL CHECK(exit_price>0),roi_pct REAL NOT NULL,observed_at TEXT NOT NULL,evaluated_at TEXT NOT NULL,status TEXT NOT NULL,model TEXT NOT NULL,window_seconds INTEGER NOT NULL);
